import{_ as a,o,c as i,a2 as n}from"./chunks/framework.CgxQ0r6v.js";const p=JSON.parse('{"title":"Planificación Académica: Redes (Trimestre 1)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Redes/Planificacion_Trimestre_II-IV.md","filePath":"materias/Redes/Planificacion_Trimestre_II-IV.md"}'),s={name:"materias/Redes/Planificacion_Trimestre_II-IV.md"};function r(d,e,t,c,l,m){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="planificacion-academica-redes-trimestre-1" tabindex="-1">Planificación Académica: Redes (Trimestre 1) <a class="header-anchor" href="#planificacion-academica-redes-trimestre-1" aria-label="Permalink to &quot;Planificación Académica: Redes (Trimestre 1)&quot;">​</a></h1><p>Este trimestre cubre la primera mitad del contenido programático (Unidades 1 a la 6), enfocándose en los fundamentos físicos, topologías y los modelos de comunicación esenciales.</p><hr><h2 id="📅-trimestre-1-fundamentos-fisicos-y-protocolos-base-unidades-1-a-6" tabindex="-1">📅 Trimestre 1: Fundamentos Físicos y Protocolos Base (Unidades 1 a 6) <a class="header-anchor" href="#📅-trimestre-1-fundamentos-fisicos-y-protocolos-base-unidades-1-a-6" aria-label="Permalink to &quot;📅 Trimestre 1: Fundamentos Físicos y Protocolos Base (Unidades 1 a 6)&quot;">​</a></h2><h3 id="📝-evaluacion-1-fundamentos-y-medios-de-comunicacion-unidades-1-y-2" tabindex="-1">📝 Evaluación 1: Fundamentos y Medios de Comunicación (Unidades 1 y 2) <a class="header-anchor" href="#📝-evaluacion-1-fundamentos-y-medios-de-comunicacion-unidades-1-y-2" aria-label="Permalink to &quot;📝 Evaluación 1: Fundamentos y Medios de Comunicación (Unidades 1 y 2)&quot;">​</a></h3><p><strong>Objetivo:</strong> Comprender los conceptos básicos de transmisión y los medios físicos.</p><ul><li>Conceptos de redes, elementos de transmisión (Emisor, Mensaje, Medio, Receptor).</li><li>Tipos de medios (Cobre, fibra, inalámbrico) y conectores (RJ45).</li><li>Implementación de cableado (Estándares 568A/568B, cables directos y cruzados).</li><li><strong>Actividad:</strong> <strong>Laboratorio Práctico de Cableado / Examen.</strong> (25%)</li></ul><h3 id="📝-evaluacion-2-componentes-y-topologias-de-red-unidades-3-y-4" tabindex="-1">📝 Evaluación 2: Componentes y Topologías de Red (Unidades 3 y 4) <a class="header-anchor" href="#📝-evaluacion-2-componentes-y-topologias-de-red-unidades-3-y-4" aria-label="Permalink to &quot;📝 Evaluación 2: Componentes y Topologías de Red (Unidades 3 y 4)&quot;">​</a></h3><p><strong>Objetivo:</strong> Identificar el hardware de red y cómo se estructura lógicamente.</p><ul><li>Dispositivos de interconexión: NIC, Switches, Routers, Hubs, Bridges.</li><li>Tipos de redes (LAN, MAN, WAN) y Topologías físicas (Bus, Estrella, Anillo, Malla).</li><li>Sistemas operativos de redes y estaciones de trabajo.</li><li><strong>Actividad:</strong> <strong>Examen Escrito / Taller de Diseño Físico.</strong> (25%)</li></ul><h3 id="📝-evaluacion-3-protocolos-y-modelos-de-comunicacion-unidad-5" tabindex="-1">📝 Evaluación 3: Protocolos y Modelos de Comunicación (Unidad 5) <a class="header-anchor" href="#📝-evaluacion-3-protocolos-y-modelos-de-comunicacion-unidad-5" aria-label="Permalink to &quot;📝 Evaluación 3: Protocolos y Modelos de Comunicación (Unidad 5)&quot;">​</a></h3><p><strong>Objetivo:</strong> Dominar las capas de comunicación que rigen las redes modernas.</p><ul><li>Modelo OSI: Análisis detallado de sus 7 capas.</li><li>Modelo TCP/IP: Arquitectura y su correspondencia con OSI.</li><li>Comunicación Cliente-Servidor vs. P2P, encapsulamiento y dominios de colisión.</li><li><strong>Actividad:</strong> <strong>Examen Escrito / Análisis de Casos.</strong> (25%)</li></ul><h3 id="📝-evaluacion-4-tecnologias-y-ancho-de-banda-unidad-6" tabindex="-1">📝 Evaluación 4: Tecnologías y Ancho de Banda (Unidad 6) <a class="header-anchor" href="#📝-evaluacion-4-tecnologias-y-ancho-de-banda-unidad-6" aria-label="Permalink to &quot;📝 Evaluación 4: Tecnologías y Ancho de Banda (Unidad 6)&quot;">​</a></h3><p><strong>Objetivo:</strong> Evaluar el rendimiento y las tecnologías subyacentes de las redes.</p><ul><li>Concepto de ancho de banda, medición y tasas de transferencia.</li><li>Tecnologías de redes LAN: Ethernet, Token Ring, FDDI.</li><li><strong>Actividad:</strong> <strong>Examen Escrito / Ejercicios de Cálculo de Rendimiento.</strong> (25%)</li></ul><hr><h2 id="✅-resumen-del-trimestre" tabindex="-1">✅ Resumen del Trimestre <a class="header-anchor" href="#✅-resumen-del-trimestre" aria-label="Permalink to &quot;✅ Resumen del Trimestre&quot;">​</a></h2><p>Al finalizar el Trimestre 1, el alumno tiene una sólida base teórica sobre cómo viaja la información (medios y protocolos) y conoce el hardware necesario para montar una red local, preparado para entrar en la configuración lógica y seguridad en el próximo trimestre.</p>',19)])])}const h=a(s,[["render",r]]);export{p as __pageData,h as default};
